import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as d,o as e,X as a}from"./chunks/vendor-vueuse.XPft87tp.js";const R=JSON.parse('{"title":"MySQL 事务","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/mysql-transaction.md","filePath":"mysql/mysql-transaction.md","lastUpdated":1786990830000}'),r={name:"mysql/mysql-transaction.md"};function n(l,t,i,s,c,E){return e(),d("div",null,t[0]||(t[0]=[a('<h1 id="mysql-事务" tabindex="-1">MySQL 事务 <a class="header-anchor" href="#mysql-事务" aria-label="Permalink to &quot;MySQL 事务&quot;">​</a></h1><h3 id="事务是一组要么全成要么全撤的操作" tabindex="-1">事务是一组要么全成要么全撤的操作 <a class="header-anchor" href="#事务是一组要么全成要么全撤的操作" aria-label="Permalink to &quot;事务是一组要么全成要么全撤的操作&quot;">​</a></h3><p>转账时扣款和入账必须落在同一个事务里：中间任何一步失败，两边都回到开始。InnoDB 用 undo 回滚（原子性），用 redo 做崩溃恢复（持久性），用锁和 MVCC 做隔离，最终保证一致性。</p><h3 id="acid-各自靠什么实现" tabindex="-1">ACID 各自靠什么实现 <a class="header-anchor" href="#acid-各自靠什么实现" aria-label="Permalink to &quot;ACID 各自靠什么实现&quot;">​</a></h3><ul><li><strong>原子性 Atomicity</strong>：中间失败就回到开始，靠 undo log。</li><li><strong>一致性 Consistency</strong>：余额不为负、约束不被破坏，是事务的目标；另外三个是手段。</li><li><strong>隔离性 Isolation</strong>：未提交的改动默认不让别的事务随便看见，靠锁和 MVCC。</li><li><strong>持久性 Durability</strong>：提交后宕机也不丢，靠 redo 刷盘；binlog 用于复制和备份。</li></ul><p>提交时 InnoDB 会对 redo 和 binlog 做<strong>两阶段提交</strong>，避免引擎和 binlog 一个写成功、一个没写，主从数据对不上。</p><h3 id="并发会破坏哪些一致性" tabindex="-1">并发会破坏哪些一致性 <a class="header-anchor" href="#并发会破坏哪些一致性" aria-label="Permalink to &quot;并发会破坏哪些一致性&quot;">​</a></h3><ul><li><strong>脏读</strong>：读到别人还没提交的改动，对方一回滚，手里就是假数据。</li><li><strong>不可重复读</strong>：同一事务两次读同一行，中间被别人改并提交，值变了。针对「行被改」。</li><li><strong>幻读</strong>：同一条件两次读，行数变了——别人插入或删除了符合条件的行。针对「行集合变了」。</li><li><strong>丢失更新</strong>：两个事务都改同一行，后提交的覆盖先提交的，没有基于最新值累加。</li></ul><p>不可重复读和幻读容易混。前者是同一行内容变了，后者是多了或少了行。</p><h3 id="隔离级别-标准表和-innodb-不是同一张图" tabindex="-1">隔离级别：标准表和 InnoDB 不是同一张图 <a class="header-anchor" href="#隔离级别-标准表和-innodb-不是同一张图" aria-label="Permalink to &quot;隔离级别：标准表和 InnoDB 不是同一张图&quot;">​</a></h3><p>SQL 标准：</p><table tabindex="0"><thead><tr><th>隔离级别</th><th>脏读</th><th>不可重复读</th><th>幻读</th></tr></thead><tbody><tr><td>READ UNCOMMITTED</td><td>可能</td><td>可能</td><td>可能</td></tr><tr><td>READ COMMITTED</td><td>否</td><td>可能</td><td>可能</td></tr><tr><td>REPEATABLE READ</td><td>否</td><td>否</td><td>标准上可能</td></tr><tr><td>SERIALIZABLE</td><td>否</td><td>否</td><td>否</td></tr></tbody></table><p>MySQL 默认 <strong>REPEATABLE READ</strong>。把标准表直接套到 InnoDB 会误判幻读：</p><ul><li>RR 下普通 <code>SELECT</code> 是快照读，同一事务反复读同一份 Read View，看不到别人后来插入的行</li><li><code>SELECT ... FOR UPDATE</code> / <code>UPDATE</code> / <code>DELETE</code> 是当前读，InnoDB 用 Next-Key Lock（记录锁 + 间隙锁）堵住间隙，减少幻读</li><li>快照读和当前读混用、自己插入后再读，仍可能感觉到「幻象」</li><li>SERIALIZABLE 的语义是「并发结果等价于某种串行顺序」，不是把所有事务排成单线程队列</li></ul><h3 id="innodb-怎样实现隔离" tabindex="-1">InnoDB 怎样实现隔离 <a class="header-anchor" href="#innodb-怎样实现隔离" aria-label="Permalink to &quot;InnoDB 怎样实现隔离&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>普通 SELECT</th><th>当前读</th></tr></thead><tbody><tr><td>READ UNCOMMITTED</td><td>读最新，几乎无 MVCC</td><td>锁</td></tr><tr><td>READ COMMITTED</td><td>每条语句一个 Read View</td><td>记录锁，语句结束可释放间隙相关锁</td></tr><tr><td>REPEATABLE READ</td><td>第一次一致性读创建 Read View，之后复用</td><td>Next-Key Lock，事务结束才放</td></tr><tr><td>SERIALIZABLE</td><td>普通 SELECT 升级成当前读（相当于加共享锁）</td><td>锁直到事务结束</td></tr></tbody></table><p>不少资料写「RC/RR 读的时候加共享锁」，那是传统锁实现。InnoDB 普通 <code>SELECT</code> 默认<strong>不加行锁</strong>，靠 MVCC 读可见版本。</p><h3 id="mvcc-用版本链换读写不阻塞" tabindex="-1">MVCC：用版本链换读写不阻塞 <a class="header-anchor" href="#mvcc-用版本链换读写不阻塞" aria-label="Permalink to &quot;MVCC：用版本链换读写不阻塞&quot;">​</a></h3><p>Multi-Version Concurrency Control 让读尽量不加锁。先分两种读：</p><ul><li><strong>快照读</strong>：普通 <code>SELECT</code>，读可见版本，不加行锁</li><li><strong>当前读</strong>：<code>SELECT ... FOR UPDATE</code>、<code>LOCK IN SHARE MODE</code>、<code>UPDATE</code>、<code>DELETE</code>，读最新并加锁</li></ul><p>行上隐藏列：</p><ul><li><code>DB_TRX_ID</code>：最后修改这条记录的事务 ID</li><li><code>DB_ROLL_PTR</code>：指向 undo 里的上一个版本</li><li><code>DB_ROW_ID</code>：没有主键时才用来生成聚簇索引</li></ul><p>更新不是把旧值原地抹掉完事，而是把旧值写进 undo，串成版本链。Read View 决定当前事务能看见链上哪一版：</p><ul><li>自己改的可见</li><li>在 Read View 创建前已提交的可见</li><li>创建时还活跃、或之后才启动的事务，其改动不可见</li></ul><p><strong>RC 和 RR 的差别主要在 Read View 何时创建</strong>：RC 每条语句新建，所以能读到其他事务已提交的新值；RR 第一次快照读建一次、后面复用，同一事务里行内容稳定。</p><p>MVCC 解决读写冲突和大部分脏读 / 不可重复读，<strong>不能替代锁去解决写写冲突和丢失更新</strong>。丢失更新要在应用层用版本号，或在数据库用 <code>SELECT ... FOR UPDATE</code>。</p>',26)]))}const u=o(r,[["render",n]]);export{R as __pageData,u as default};
